            "endingText": "<p>You have given the Union your body, your health, and your soul. In return it has given you four more years to mold the continent in your vision. Charles La Follette does not intend on wasting it.\n\n<p>President La Follette, you, will go down as a transformational figure in American politics. You make speeches to crowds, talking about your common-sense plans to reform North America now that the Union has hegemony, at the same time you sign laws that radically transform every aspect of life. A federal healthcare system is passed, Southern society is transformed, and Unions and Worker Councils are empowered. The Mormons and Canadians remain a thorn in your side, but none can say you haven’t tried to deal with them in your own way.\n\n<p>You win a second term easily in 1948, ushering in the final death of the Republican Party as their last representatives in Congress are replaced by Socialists. Charles La Follette will pass away, sickly yet successful, in 1951. Not even God -- Harry Turtledove -- could’ve foreseen a Presidency as transformational as yours.",
